n = int(input())
if n == 0:
    pass
else:
    for _ in range(n):
        val, rand = map(int, input().split())
        print(val, rand)

starterCode.cpp:
#include <iostream>
using namespace std;
int main() {
    int n; cin >> n;
    for(int i=0; i<n; i++) {
        int v, r; cin >> v >> r;
        cout << v << " " << r << "\n";
    }
    return 0;
}

starterCode.java:
import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        for (int i=0; i<n; i++) {
            System.out.println(sc.nextInt() + " " + sc.nextInt());
        }
    }
}
